# ============================================================
# Global Variables (glob)
# ============================================================

glob MAX_SIZE: int = 100;
glob greeting: str = "Hello";

def use_global() {
    greeting = "Hola";        # Assignment rebinds the module-level glob
}

def shadow_global() {
    greeting: str = "Hi";     # Typed declaration = new local; glob untouched
    print(greeting);
}


# ============================================================
# Compile-Time Evaluation (comptime)
# ============================================================
# `comptime` values are computed by the compiler and folded into the program.
# See reference/language/comptime.md for the full rules and intrinsics.

comptime import from jaclang.comptime { members }

enum Kind { A, B }

comptime KINDS: int = len(members(Kind));   # 2, evaluated at compile time
comptime assert KINDS == 2, "two kinds";     # fails the build, never runs

def repeat(comptime n: int, msg: str) -> str {
    out = "";
    comptime for _ in range(n) {              # unrolled per call-site value
        out += msg;
    }
    return out;
}

obj Grid[T, comptime rows: int, comptime cols: int] {
    has cells: list[T];
    comptime SIZE: int = rows * cols;         # Grid[int, 2, 3].SIZE folds to 6
}


# ============================================================
# Impl Blocks (separate declaration from definition)
# ============================================================

obj Calculator {
    has value: int = 0;

    # Declare methods (no body)
    def add(n: int) -> int;
    def multiply(n: int) -> int;
}

# Define methods separately (can be in a .impl.jac file)
impl Calculator.add(n: int) -> int {
    self.value += n;
    return self.value;
}

impl Calculator.multiply(n: int) -> int {
    self.value *= n;
    return self.value;
}


# ============================================================
# Lambdas
# ============================================================

with entry {
    # Simple lambda: params always parenthesized, body always braced.
    # A body that is exactly one expression statement is the implicit return.
    add = lambda (x: int, y: int) { x + y; };
    print(add(3, 4));

    # Typed lambda with return type
    mul = lambda (x: int, y: int) -> int { x * y; };
    print(mul(3, 4));

    # Multi-statement lambda: explicit `return` or a semicolon-less tail expression
    # (without either, the lambda returns None)
    classify = lambda (score: int) -> str {
        if score >= 90 { return "A"; }
        elif score >= 80 { return "B"; }
        else { return "F"; }
    };
    print(classify(85));

    # Tail-expression return in a multi-statement callback position
    scaled = list(
        map(
            lambda (x: int) -> int {
                y = x + 1;
                y * 2
            },
            [1, 2, 3]
        )
    );
    print(scaled);  # [2, 4, 6]

    # No-arg lambda
    get_42 = lambda { 42; };

    # Void lambda (common in JSX event handlers)
    handler = lambda -> None { print("clicked"); };
}


# ============================================================
# Pipe Operators
# ============================================================

with entry {
    # Forward pipe: value |> function
    "hello" |> print;
    5 |> str |> print;

    # Backward pipe: function <| value
    print <| "world";

    # Chained pipes
    [3, 1, 2] |> sorted |> list |> print;
}


