# ============================================================
# AI INTEGRATION (by llm)
# ============================================================
# Jac's Meaning Typed Programming lets the compiler
# extract semantics from your code to construct LLM prompts.


# ============================================================
# by llm() -- Delegate Function to LLM
# ============================================================

# The function signature IS the specification.
# Name, param names, types, and return type become the prompt.

def classify_sentiment(text: str) -> str by llm;

# Enums constrain LLM output to valid values
enum Category { WORK, PERSONAL, SHOPPING, HEALTH, OTHER }
def categorize(title: str) -> Category by llm();

# Structured output -- every field must be filled
obj Ingredient {
    has name: str,
        cost: float,
        carby: bool;
}
def plan_shopping(recipe: str) -> list[Ingredient] by llm();

# Model configuration
def summarize(text: str) -> str by llm(
    model_name="gpt-4",
    temperature=0.7,
    max_tokens=2000
);

# Streaming response (returns generator)
def stream_story(prompt: str) -> str by llm(stream=True);

# Inline LLM expression
with entry {
    result = "Explain quantum computing simply" by llm;
}


# ============================================================
# sem -- Semantic Descriptions for AI
# ============================================================
# `sem` attaches descriptions to bindings that the compiler
# includes in the LLM prompt. It's not a comment -- it
# changes what the LLM sees at runtime.

sem Ingredient.cost = "Estimated cost in USD";
sem Ingredient.carby = "True if high in carbohydrates";

sem plan_shopping = "Generate a shopping list for the given recipe.";

# Parameter-level semantics
sem summarize.text = "The article or document to summarize";
sem summarize.return = "A 2-3 sentence summary";

# Enum value semantics
enum Priority { LOW, MEDIUM, HIGH, CRITICAL }
sem Priority.CRITICAL = "Requires immediate attention within 1 hour";


# ============================================================
# Tool Calling (Agentic AI)
# ============================================================
# Give the LLM access to functions it can call (ReAct loop)

def get_weather(city: str) -> str {
    return f"Weather data for {city}";
}

def search_web(query: str) -> list[str] {
    return [f"Result for {query}"];
}

# The LLM decides which tools to call and in what order
def answer_question(question: str) -> str by llm(
    tools=[get_weather, search_web]
);

# Additional context injection
glob company_info = "TechCorp, products: CloudDB, SecureAuth";

def support_agent(question: str) -> str by llm(
    incl_info={"company": company_info}
);
sem support_agent = "Answer customer questions about our products.";


# ============================================================
# Multimodal AI
# ============================================================

import from jaclang.byllm.lib { Image }

def describe_image(image: Image) -> str by llm;

with entry {
    desc = describe_image(Image("photo.jpg"));
    desc = describe_image(Image("https://example.com/img.png"));
}


# ============================================================
# Ownership & Borrowing (opt-in)
# ============================================================
# `own` marks a unique owner; assigning it elsewhere or passing it
# to a call MOVES the value (use-after-move is a compile error).
# `&`/`&mut` take a shared/mutable borrow; `imm` is deep-immutable.
# Unannotated bindings are untouched -- the checker only tracks
# what you tag. On native, full coverage enables zero-RC builds
# (jac build --native --memory nogc).

obj Buffer { has n: int = 0; }

def use_buf(x: Buffer) -> None {}

with entry {
    a: own Buffer = Buffer();   # unique owner
    v: &Buffer = &a;            # shared borrow (owner is read-only while live)
    use_buf(v);
    m: imm Buffer = Buffer();   # deep-immutable: no writes through `m`, ever
    b = a;                      # moves out of `a`; reading `a` again is E1301
}

# `in <handle> { }` opens a Region for allocation: everything created
# under the open is reclaimed wholesale when the handle drops, and
# references must not outlive it. `in Region() { }` is the anonymous,
# block-scoped form.
def scratch() -> None {
    in Region() {
        tmp = Buffer();   # reclaimed with the region at `}`
    }
    r: own Region = Region();
    in r {
        keep = Buffer();  # reclaimed when `r` drops (scope exit here)
    }
}

# `def drop` runs exactly once when the object is destroyed, at its
# owner's last use (native backend; Python does not call it yet).
obj Res {
    has fd: int = 0;

    def drop {
        print("closing", self.fd);
    }
}


# ============================================================
# FULL-STACK DEVELOPMENT (Codespaces)
# ============================================================
# Jac code can target different execution environments.
# The codespace is INFERRED -- there is no placement syntax:
#   JSX / "npm" string import => declaration placed client; placement
#                                propagates (scope-aware, across
#                                modules) to helpers, globs, and
#                                imports the client code uses
#   python imports, node/edge/walker archetypes, ::py:: blocks,
#   typed context blocks      => server anchors (server is also the
#                                default for unreferenced pure code)
#   def:pub / walkers         => stay server endpoints (client calls
#                                become RPC bridges automatically)
#   C extern-decl import      => declaration placed native; consumers
#                                follow (importing a native module is
#                                NOT a signal; pure code stays server)
# Overrides live in jac.toml, not in source:
#   [placement.pins] "mod.elem" = "server" | "client" | "native"
# Review with `jac check <entry> --placements` (evidence per element).
# (The old sv/cl/na markers no longer parse -- `jac fix placement`
# migrates marker-era code.)

# A mixed module -- every placement below is inferred:

# Server code (a node archetype anchors the module server)
node Todo {
    has title: str, done: bool = False;
}

def:pub get_todos() -> list[any] {
    return [{"title": t.title} for t in [root -->][?:Todo]];
}

# Client code (compiles to JavaScript/React): the JSX return places
# app() client; its call to get_todos() bridges over RPC.
def:pub app() -> JsxElement {
    has items: list = [];

    async can with entry {
        items = await get_todos();
    }

    return <div>
        {[<p key={i.title}>{i.title}</p> for i in items]}
    </div>;
}

# Still server -- placement is per-element, not positional
node Secret { has value: str; }


# ============================================================
# jac.toml placement + app tables
# ============================================================
# (TOML, shown here for adjacency)
#
#   [placement.pins]              # override inference (fnmatch keys)
#   "main.API_KEY" = "server"     #   keep a glob out of the JS bundle
#   "kernels.*"    = "native"     #   whole-module performance mandate
#
