# <div className="cls">         Class name (not "class")
# <div style={{"color": "red"}} Inline styles
#   (classes declared in a same-base-name <Comp>.style.css are auto-scoped)
# <@expr>...</@expr>            Dynamic tag (tag chosen by expression)


